def _backfill_allocations() -> None:
    """Existing khatas get allocation rows: live payments, oldest first, against live udhaar, oldest due
    first (udhaar without a due date last). Self-contained so later app changes can't alter it."""
    le = sa.table("ledger_entries", sa.column("id", sa.Uuid), sa.column("merchant_id", sa.Uuid),
                  sa.column("customer_id", sa.Uuid), sa.column("type", sa.String), sa.column("amount_paise", sa.BigInteger),
                  sa.column("due_date", sa.Date), sa.column("reverses_entry_id", sa.Uuid),
                  sa.column("created_at", sa.DateTime(timezone=True)))
    pa = sa.table("payment_allocations", sa.column("id", sa.Uuid), sa.column("merchant_id", sa.Uuid),
                  sa.column("customer_id", sa.Uuid), sa.column("payment_entry_id", sa.Uuid),
                  sa.column("credit_entry_id", sa.Uuid), sa.column("amount_paise", sa.BigInteger),
                  sa.column("created_at", sa.DateTime(timezone=True)))
    conn = op.get_bind()
    rows = conn.execute(sa.select(le).order_by(le.c.customer_id, le.c.created_at)).all()
    by_customer: dict = {}
    for r in rows:
        by_customer.setdefault(r.customer_id, []).append(r)
    now = datetime.now(timezone.utc)
    out = []
    for customer_id, entries in by_customer.items():
        gone = {r.reverses_entry_id for r in entries if r.type == "REVERSAL"}
        live = [r for r in entries if r.type != "REVERSAL" and r.id not in gone]
        credits = sorted((r for r in live if r.type == "CREDIT"),
                         key=lambda r: (r.due_date is None, r.due_date or date.max, r.created_at))
        left = {r.id: r.amount_paise for r in credits}
        for pay in (r for r in live if r.type == "PAYMENT"):
            amount = pay.amount_paise
            for c in credits:
                if not amount:
                    break
                used = min(amount, left[c.id])
                if used:
                    out.append({"id": uuid.uuid4(), "merchant_id": pay.merchant_id, "customer_id": customer_id,
                                "payment_entry_id": pay.id, "credit_entry_id": c.id, "amount_paise": used,
                                "created_at": now})
                    left[c.id] -= used
                    amount -= used
    if out:
        conn.execute(pa.insert(), out)


